from pathlib import Path
import re

main_path = Path('confectionery_order_app/app/src/main/java/com/example/confectionery/MainActivity.kt')
text = main_path.read_text(encoding='utf-8')

# Keep only temporary targets for the single contact explicitly chosen by the user.
anchor = '    private var photoCallback: ((Uri) -> Unit)? = null\n'
if anchor not in text:
    raise SystemExit('photoCallback anchor missing')
insert = anchor + '''    private var contactNameTarget: EditText? = null\n    private var contactPhoneTarget: EditText? = null\n\n    private val phoneContactPicker = registerForActivityResult(ActivityResultContracts.StartActivityForResult()) { result ->\n        if (result.resultCode != android.app.Activity.RESULT_OK) return@registerForActivityResult\n        val uri = result.data?.data ?: return@registerForActivityResult\n        val projection = arrayOf(\n            android.provider.ContactsContract.CommonDataKinds.Phone.DISPLAY_NAME,\n            android.provider.ContactsContract.CommonDataKinds.Phone.NUMBER\n        )\n        runCatching {\n            contentResolver.query(uri, projection, null, null, null)?.use { cursor ->\n                if (!cursor.moveToFirst()) return@use\n                val nameIndex = cursor.getColumnIndex(android.provider.ContactsContract.CommonDataKinds.Phone.DISPLAY_NAME)\n                val phoneIndex = cursor.getColumnIndex(android.provider.ContactsContract.CommonDataKinds.Phone.NUMBER)\n                val selectedName = if (nameIndex >= 0) cursor.getString(nameIndex).orEmpty() else \"\"\n                val selectedPhone = if (phoneIndex >= 0) cursor.getString(phoneIndex).orEmpty() else \"\"\n                if (selectedName.isNotBlank()) contactNameTarget?.setText(selectedName)\n                if (selectedPhone.isNotBlank()) contactPhoneTarget?.setText(selectedPhone)\n            }\n        }.onSuccess {\n            toast(\"Phone contact منتخب ہوگیا — باقی customer details مکمل کریں\")\n        }.onFailure {\n            toast(\"Contact پڑھا نہیں جا سکا\")\n        }\n        contactNameTarget = null\n        contactPhoneTarget = null\n    }\n'''
text = text.replace(anchor, insert, 1)

# Replace customer creation with manual + phone-contact import in one form.
pattern = r'    private fun showAddCustomer\(\) \{.*?\n    \}\n\n    private fun showProducts'
replacement = '''    private fun showAddCustomer() {\n        reset(\"Add Customer\")\n        back { showCustomers() }\n        info(\"Customer کو manually درج کریں، یا Phone Contacts سے نام اور نمبر منتخب کریں۔ Phone number لازمی نہیں ہے۔\")\n\n        var photoUri: String? = null\n        val photo = image(null, 150)\n        root.addView(photo)\n        button(\"Choose Customer Photo (optional)\") {\n            photoCallback = { uri ->\n                runCatching { ImageStore.importImage(this, uri, \"customer\") }\n                    .onSuccess { stored -> photoUri = stored; photo.setImageURI(Uri.parse(stored)) }\n                    .onFailure { toast(\"Image save failed\") }\n            }\n            photoPicker.launch(arrayOf(\"image/*\"))\n        }\n\n        sectionTitle(\"Customer Details\")\n        val name = edit(\"Customer / Shopkeeper Name *\")\n        val phone = edit(\"Phone Number (optional)\")\n        button(\"📱 Add from Phone Contacts\") {\n            contactNameTarget = name\n            contactPhoneTarget = phone\n            val intent = Intent(\n                Intent.ACTION_PICK,\n                android.provider.ContactsContract.CommonDataKinds.Phone.CONTENT_URI\n            )\n            phoneContactPicker.launch(intent)\n        }\n        info(\"Phone Contacts میں search/alphabet سے contact منتخب کریں؛ نام اور منتخب phone number خود اوپر آ جائیں گے۔\")\n\n        val shop = edit(\"Shop / Business Name (optional)\")\n        val area = edit(\"Area / Route (optional)\").apply {\n            if (prefs.deviceAreaName.isNotBlank()) setText(prefs.deviceAreaName)\n        }\n        val address = edit(\"Address (optional)\")\n        val credit = edit(\"Credit Limit (optional)\", numeric = true)\n        val opening = edit(\"Opening Balance (optional)\", numeric = true)\n\n        button(\"Save Customer\") {\n            if (txt(name).isBlank()) return@button toast(\"Customer name ضروری ہے\")\n            lifecycleScope.launch {\n                val cleanPhone = txt(phone).trim()\n                if (cleanPhone.isNotBlank()) {\n                    val duplicate = db.customerDao().all().firstOrNull {\n                        it.phone.filter(Char::isDigit).isNotBlank() &&\n                            it.phone.filter(Char::isDigit) == cleanPhone.filter(Char::isDigit)\n                    }\n                    if (duplicate != null) {\n                        toast(\"یہ phone number پہلے ${duplicate.name} کے نام سے موجود ہے\")\n                        return@launch\n                    }\n                }\n                db.customerDao().insert(\n                    CustomerEntity(\n                        name = txt(name).trim(),\n                        phone = cleanPhone,\n                        shopName = txt(shop).trim(),\n                        address = txt(address).trim(),\n                        photoUri = photoUri,\n                        creditLimit = txt(credit).toDoubleOrNull() ?: 0.0,\n                        balance = txt(opening).toDoubleOrNull() ?: 0.0,\n                        areaName = txt(area).trim().ifBlank { prefs.deviceAreaName }\n                    )\n                )\n                queueSync()\n                toast(\"Customer محفوظ ہوگیا\")\n                showCustomers()\n            }\n        }\n    }\n\n    private fun showProducts'''
text, n = re.subn(pattern, lambda m: replacement, text, count=1, flags=re.S)
if n != 1:
    raise SystemExit('showAddCustomer replace failed')

main_path.write_text(text, encoding='utf-8')
print('V11 phone contact customer import patch applied')
